def trans1(g):
 R,C=len(g),len(g[0]); ms=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]==2 and any(0<=r+dr<R and 0<=c+dc<C and g[r+dr][c+dc]==3 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):ms.append((r,c))
 return [[1 if v==3 and any(abs(r-a)<=1 and abs(c-b)<=1 for a,b in ms) else v for c,v in enumerate(row)] for r,row in enumerate(g)]
out=trans1(grid)
print('\n'.join('['+','.join(map(str,r))+'],' for r in out))

